// Shared helpers for auditing the Cell Simulator's authored content tables.
//
// The failure this exists for: a table's "facts" were generated by cycling a short list of
// values in id order (habitat = ['Various','Aquatic','Soil','Mammalian host','Marine'][i % 5],
// and so on), so E. coli read "Culturable: Difficult" and the syphilis spirochete read
// "Pathogenicity: None". Every value is a real-looking word, so spell-checks, schema checks and
// "no undefined" gates all pass; only the PATTERN gives it away.
import { createRequire } from 'node:module';
import { resolve } from 'node:path';

// Resolve from the repo (process.cwd()) so this file works both in a scratch lane folder and
// once installed under tests/.
const { parse } = createRequire(resolve(process.cwd(), 'tests/_resolve.js'))('acorn');

function walk(node, visit) {
  if (!node || typeof node !== 'object') return;
  if (Array.isArray(node)) { node.forEach((n) => walk(n, visit)); return; }
  if (typeof node.type !== 'string') return;
  visit(node);
  for (const k of Object.keys(node)) {
    if (k === 'type' || k === 'loc' || k === 'start' || k === 'end') continue;
    walk(node[k], visit);
  }
}

/** Evaluate the named `var NAME = [ ...literal... ]` tables from the tool source. */
export function extractTables(source, names) {
  const ast = parse(source, { ecmaVersion: 2022, sourceType: 'script' });
  const out = {};
  walk(ast, (n) => {
    if (n.type === 'VariableDeclarator' && n.id && n.id.type === 'Identifier' && names.includes(n.id.name)
        && n.init && n.init.type === 'ArrayExpression') {
      // eslint-disable-next-line no-new-func
      out[n.id.name] = (new Function('return ' + source.slice(n.init.start, n.init.end)))();
    }
  });
  return out;
}

function inIdOrder(rows) {
  const objs = rows.filter((r) => r && typeof r === 'object');
  const numeric = objs.every((r) => typeof r.id === 'number');
  return numeric ? objs.slice().sort((a, b) => a.id - b.id) : objs;
}

function matchRate(vals, lag) {
  let same = 0; let total = 0;
  for (let i = 0; i + lag < vals.length; i++) { total++; if (vals[i] === vals[i + lag]) same++; }
  return total ? same / total : 0;
}

/**
 * Find filler patterns in one table.
 *  - cycle: a field whose value repeats every p rows (2 <= p <= maxPeriod) at >= threshold, while
 *    neighbouring rows mostly differ (so a table sorted into blocks, like a kingdom column, does not
 *    count) and the field has no more distinct values than the period.
 *  - constant: a text field with the same value in every row.
 *  - duplicateTitles: the same heading value on more than one row.
 *  - boilerplate (advisory): one long text value reused on >= 25% of rows.
 */
export function auditTable(rows, opts = {}) {
  const { titleKey = null, maxPeriod = 12, threshold = 0.9, minRows = 8 } = opts;
  const ordered = inIdOrder(Array.isArray(rows) ? rows : []);
  const keys = [];
  ordered.forEach((r) => Object.keys(r).forEach((k) => { if (!keys.includes(k)) keys.push(k); }));
  const cycles = []; const constants = []; const boilerplate = [];
  for (const key of keys) {
    if (key === 'id') continue;
    const present = ordered.filter((r) => r[key] !== undefined && r[key] !== null);
    if (present.length < minRows) continue;
    if (present.every((r) => typeof r[key] === 'boolean')) continue;
    const vals = present.map((r) => JSON.stringify(r[key]));
    const distinct = new Set(vals).size;
    if (distinct === 1 && typeof present[0][key] === 'string') constants.push({ key, value: present[0][key] });
    const lag1 = matchRate(vals, 1);
    for (let p = 2; p <= maxPeriod && p * 2 <= vals.length; p++) {
      const rate = matchRate(vals, p);
      if (rate >= threshold && lag1 <= 0.5 && distinct <= p) {
        cycles.push({ key, period: p, rate: Number(rate.toFixed(2)), distinct, sample: [...new Set(vals)].slice(0, p).map((v) => JSON.parse(v)) });
        break;
      }
    }
    const counts = {};
    present.forEach((r) => { if (typeof r[key] === 'string' && r[key].length >= 20) counts[r[key]] = (counts[r[key]] || 0) + 1; });
    for (const [value, count] of Object.entries(counts)) {
      if (count >= 5 && count / present.length >= 0.25) boilerplate.push({ key, value, count });
    }
  }
  const duplicateTitles = [];
  if (titleKey) {
    const seen = {};
    ordered.forEach((r) => { const t = typeof r[titleKey] === 'string' ? r[titleKey].trim().toLowerCase() : null; if (t) seen[t] = (seen[t] || 0) + 1; });
    for (const [title, count] of Object.entries(seen)) if (count > 1) duplicateTitles.push({ title, count });
  }
  return { rows: ordered.length, cycles, constants, duplicateTitles, boilerplate };
}

/** Library registry rows -> { TABLE_ID: titleKey }, read from the tool source. */
export function libraryTitleKeys(source) {
  const out = {};
  const re = /\{ id: '([A-Z0-9_]+)', title: '[^']+', group: '[^']+', titleKey: '([^']+)', data: [A-Z0-9_]+ \}/g;
  for (const m of source.matchAll(re)) out[m[1]] = m[2];
  return out;
}

// Tables this lane corrected: findings here FAIL the suite.
export const ENFORCED_TABLES = ['MICROBE_SPECIES', 'HUMAN_CELLS', 'ORGANELLE_ATLAS', 'EVOLUTION_LINEAGES', 'CELL_CAREERS', 'LESSON_PLANS', 'CELL_TRIVIA'];
// Library tables owned by other work streams: findings are REPORTED (console) until they are
// cleaned up, then each table should move into ENFORCED_TABLES.
export const REPORTED_TABLES = ['FAMOUS_EXPERIMENTS', 'MICRO_MYTHS', 'CELL_RECORDS', 'MICROSCOPY', 'CELL_QUOTES', 'CASE_STUDIES',
  'LAB_SAFETY', 'STUDY_QS', 'MICRO_CASES', 'METABOLIC_PATHWAYS', 'SIGNAL_PATHWAYS', 'MICRO_NICHES', 'ANTIBIOTICS', 'INHERITANCE',
  'DNA_REFERENCE', 'QUICK_FACTS', 'MICROBIOME_STUDIES', 'CELL_PROCESSES', 'LAB_EQUIPMENT'];

export function hasFindings(audit) {
  return audit.cycles.length + audit.constants.length + audit.duplicateTitles.length > 0;
}
